package com.arena.core.facility;
import com.arena.core.training.*;
import com.arena.core.repository.*;
import com.arena.core.service.*;
import com.arena.core.exception.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.security.oauth2.jwt.Jwt;
import java.util.*;import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class FacilityServiceTest {
 AcademyAuthorization auth=mock(AcademyAuthorization.class);AcademySportRepository sports=mock(AcademySportRepository.class);AcademyPlayAreaRepository areas=mock(AcademyPlayAreaRepository.class);FacilityLedger ledger=mock(FacilityLedger.class);AuditService audit=mock(AuditService.class);ObjectMapper json=new ObjectMapper();
 FacilityService service=new FacilityService(auth,sports,areas,ledger,audit,json,mock(AuditEventRepository.class),mock(AcademySetupService.class),mock(CustomerRepository.class));Jwt jwt=Jwt.withTokenValue("unit").header("alg","none").subject("owner").build();AcademySport sport;AcademyPlayArea facility;UUID key=UUID.randomUUID();
 @BeforeEach void setup(){when(auth.manage(jwt)).thenReturn(new AcademyAuthorization.Actor(com.arena.core.entity.AppUserEntity.builder().customerId(10L).build(),null,Set.of("OWNER")));when(auth.actor(jwt)).thenReturn(new AcademyAuthorization.Actor(com.arena.core.entity.AppUserEntity.builder().customerId(10L).build(),null,Set.of("OWNER")));sport=new AcademySport();sport.setId(20L);sport.setAcademyId(10L);sport.setCatalogueCode("SNOOKER");sport.setActive(true);sport.setSessions(true);when(sports.findById(20L)).thenReturn(Optional.of(sport));facility=new AcademyPlayArea();facility.setId(30L);facility.setAcademyId(10L);facility.setSportId(20L);facility.setVersion(0L);facility.setCode("E1");facility.setFacilityType("ENGLISH");facility.setActive(true);when(areas.locked(10L,30L)).thenReturn(Optional.of(facility));when(areas.saveAndFlush(any())).thenAnswer(i->{AcademyPlayArea f=i.getArgument(0);if(f.getId()==null)f.setId(30L);if(f.getVersion()==null)f.setVersion(0L);return f;});when(ledger.allocate(any(),any(),any(),any(),anyInt())).thenReturn(1L);}
 JsonNode body(String text)throws Exception{return json.readTree(text);}
 @Test void mixedCreationIsUnconfiguredAndAudited()throws Exception{var result=service.create(jwt,10L,20L,key,body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":2},{\"facilityType\":\"POOL\",\"count\":1}]}"));assertEquals(List.of("E1","E2","P1"),result.facilities().stream().map(FacilityContracts.View::code).toList());assertTrue(result.facilities().stream().allMatch(f->f.active()&&!f.configured()&&f.hourlyRate()==null));verify(audit,times(3)).record(eq("FACILITY_CREATED"),eq(10L),any(),eq("owner"),isNull(),anyString(),isNull(),anyString());verify(ledger).remember(eq(10L),eq(20L),eq(key),any(),any());}
 @Test void invalidTypesCountsAndInjectedCodesNeverWrite()throws Exception{for(String entry:List.of("{\"facilityType\":\"COURT\",\"count\":1}","{\"facilityType\":\"ENGLISH\",\"count\":0}","{\"facilityType\":\"ENGLISH\",\"count\":1.5}","{\"facilityType\":\"ENGLISH\",\"count\":1,\"code\":\"E9\"}"))assertThrows(FacilityFailure.class,()->service.create(jwt,10L,20L,key,body("{\"facilities\":["+entry+"]}")));verify(areas,never()).saveAndFlush(any());}
 @Test void duplicateTypeRejected()throws Exception{assertThrows(FacilityFailure.class,()->service.create(jwt,10L,20L,key,body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1},{\"facilityType\":\"ENGLISH\",\"count\":1}]}")));verifyNoInteractions(ledger);}
 @Test void ownershipAndCapabilityEnforced()throws Exception{assertThrows(ArenaOpsException.class,()->service.list(jwt,99L,20L));sport.setSessions(false);assertEquals(ErrorCode.FACILITY_CAPABILITY_DISABLED,assertThrows(FacilityFailure.class,()->service.create(jwt,10L,20L,key,body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1}]}"))).getErrorCode());verify(areas,never()).saveAndFlush(any());}
 @Test void patchMissingFieldsRemainAndExplicitNullClears()throws Exception{facility.setHourlyRate(new BigDecimal("150.00"));facility.setFrameRate(new BigDecimal("50.00"));facility.setDisplayName("VIP");service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"displayName\":null,\"frameRate\":null}]}"));assertEquals(new BigDecimal("150.00"),facility.getHourlyRate());assertNull(facility.getFrameRate());assertNull(facility.getDisplayName());assertTrue(FacilityContracts.configured(facility));}
 @Test void staleVersionReturnsSafeConflictBeforeWriting()throws Exception{var failure=assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":9,\"hourlyRate\":200}]}")));assertEquals(ErrorCode.FACILITY_VERSION_CONFLICT,failure.getErrorCode());assertEquals(30L,failure.getConflicts().get(0).get("facilityId"));verify(areas,never()).saveAndFlush(any());verifyNoInteractions(audit);}
 @Test void invalidMoneyAndCourtFrameRateRejected()throws Exception{for(String rate:List.of("-1","0","1.234","\"100\"","10000000000"))assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"hourlyRate\":"+rate+"}]}")));facility.setFacilityType("COURT");assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"frameRate\":100}]}")));verify(areas,never()).saveAndFlush(any());}
 @Test void disabledCapabilityAllowsOnlySafeDeactivationAndHistoricalRead()throws Exception{sport.setSessions(false);when(areas.findByAcademyIdAndSportIdOrderById(10L,20L)).thenReturn(List.of(facility));assertEquals(1,service.list(jwt,10L,20L).facilities().size());service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"active\":false}]}"));assertFalse(facility.isActive());assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"active\":true}]}")));}
 @Test void coachCannotReachFacilityRepository(){when(auth.manage(jwt)).thenThrow(new ArenaOpsException(ErrorCode.ACCESS_DENIED));assertThrows(ArenaOpsException.class,()->service.list(jwt,10L,20L));verifyNoInteractions(areas,sports);}
 @Test void eligibilityGuardRequiresConfiguredActiveFacilityAndSavedCapability(){assertThrows(FacilityFailure.class,()->service.requireEligibleLocked(jwt,10L,30L));facility.setHourlyRate(new BigDecimal("150.00"));assertSame(facility,service.requireEligibleLocked(jwt,10L,30L));facility.setActive(false);assertThrows(FacilityFailure.class,()->service.requireEligibleLocked(jwt,10L,30L));facility.setActive(true);sport.setSessions(false);assertThrows(FacilityFailure.class,()->service.requireEligibleLocked(jwt,10L,30L));}
 @Test void moneyParsingNeverRoundsThroughBinaryFloatingPoint(){var body=service.parse("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"hourlyRate\":1.000000000000000000001}]}".getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body));verify(areas,never()).saveAndFlush(any());}
 @Test void badmintonUsesCourtCodesAndUnsupportedSportsCannotGenerate()throws Exception{sport.setCatalogueCode("BADMINTON");var rows=service.create(jwt,10L,20L,key,body("{\"facilities\":[{\"facilityType\":\"COURT\",\"count\":2}]}"));assertEquals(List.of("C1","C2"),rows.facilities().stream().map(FacilityContracts.View::code).toList());sport.setCatalogueCode("CRICKET");assertThrows(FacilityFailure.class,()->service.create(jwt,10L,20L,UUID.randomUUID(),body("{\"facilities\":[{\"facilityType\":\"COURT\",\"count\":1}]}")));}
 @Test void committedReplayReturnsOriginalResultEvenAfterCapabilityDisabledAndRejectsDifferentPayload()throws Exception{var stored=new java.util.concurrent.atomic.AtomicReference<FacilityLedger.Replay>();when(ledger.replay(eq(10L),eq(key))).thenAnswer(i->Optional.ofNullable(stored.get()));doAnswer(i->{stored.set(new FacilityLedger.Replay(i.getArgument(3),i.getArgument(4)));return null;}).when(ledger).remember(eq(10L),eq(20L),eq(key),any(),any());var input=body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1}]}" );var first=service.create(jwt,10L,20L,key,input);sport.setSessions(false);assertEquals(first,service.create(jwt,10L,20L,key,input));assertEquals(ErrorCode.FACILITY_IDEMPOTENCY_CONFLICT,assertThrows(FacilityFailure.class,()->service.create(jwt,10L,20L,key,body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":2}]}"))).getErrorCode());verify(areas,times(1)).saveAndFlush(any());}
 @Test void patchRejectsClientCodeAndDuplicateRecordIds()throws Exception{assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"code\":\"E99\"}]}")));assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"active\":false},{\"facilityId\":30,\"version\":0,\"active\":false}]}")));verify(areas,never()).saveAndFlush(any());}
 @Test void unchangedConfigurationDoesNotCreateAnAuditChange()throws Exception{var result=service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"active\":true}]}"));assertEquals(0L,result.facilities().get(0).version());verify(areas,never()).saveAndFlush(any());verifyNoInteractions(audit);}
 @Test void staffCanUseEligibleFacilityButCannotManageConfiguration(){facility.setHourlyRate(new BigDecimal("220"));var actor=new AcademyAuthorization.Actor(com.arena.core.entity.AppUserEntity.builder().customerId(10L).build(),null,Set.of("STAFF"));when(auth.actor(jwt)).thenReturn(actor);when(auth.manage(jwt)).thenThrow(new ArenaOpsException(ErrorCode.ACCESS_DENIED));assertSame(facility,service.requireEligibleLocked(jwt,10L,30L));assertThrows(ArenaOpsException.class,()->service.context(jwt));assertThrows(ArenaOpsException.class,()->service.requireEligibleLocked(jwt,99L,30L));}
 @Test void nonOperatorsCannotUseEligibleFacility(){facility.setHourlyRate(new BigDecimal("220"));when(auth.actor(jwt)).thenReturn(new AcademyAuthorization.Actor(com.arena.core.entity.AppUserEntity.builder().customerId(10L).build(),null,Set.of("STUDENT")));assertThrows(ArenaOpsException.class,()->service.requireEligibleLocked(jwt,10L,30L));}

 @Test void inactiveSportIsReadOnlyIncludingDeactivationAndSessionStart()throws Exception{
  sport.setActive(false);facility.setHourlyRate(new BigDecimal("220.00"));when(areas.findByAcademyIdAndSportIdOrderById(10L,20L)).thenReturn(List.of(facility));
  assertEquals(1,service.list(jwt,10L,20L).facilities().size());
  for(String change:List.of("\"active\":false","\"active\":true","\"displayName\":\"New\"","\"hourlyRate\":300","\"frameRate\":50"))assertEquals(ErrorCode.FACILITY_CAPABILITY_DISABLED,assertThrows(FacilityFailure.class,()->service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,"+change+"}]}"))).getErrorCode());
  assertThrows(FacilityFailure.class,()->service.create(jwt,10L,20L,key,body("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1}]}")));
  assertThrows(FacilityFailure.class,()->service.requireEligibleLocked(jwt,10L,30L));
  assertTrue(facility.isActive());assertEquals(new BigDecimal("220.00"),facility.getHourlyRate());verify(areas,never()).saveAndFlush(any());
  sport.setActive(true);assertSame(facility,service.requireEligibleLocked(jwt,10L,30L));service.patch(jwt,10L,body("{\"facilities\":[{\"facilityId\":30,\"version\":0,\"hourlyRate\":300}]}"));assertEquals(new BigDecimal("300.00"),facility.getHourlyRate());
 }
}
